-- Ca hoc, diem danh, nhan xet: cung ngay/ma voi du lieu JSON giao dien.
DO $seed$
DECLARE c record; e record; b text; d date; k text; times text[]; start_at timestamptz; end_at timestamptz; completed boolean; gv text; h record;
BEGIN
 FOR c IN SELECT * FROM vuihoc."LOP_HOC" WHERE madinhdanh LIKE 'TEST-CLS-%' LOOP
  FOR e IN SELECT key,value FROM jsonb_each(c.chitietcahoc) LOOP
   d:=left(e.value->>'dateStr',10)::date;
   SELECT madinhdanh,regexp_split_to_array(khoanggio,'\s*-\s*') INTO k,times FROM vuihoc."KHUNG_GIO"
    WHERE regexp_replace(khoanggio,'\s','','g')=regexp_replace(substr(e.value->>'dateStr',12),'\s','','g') LIMIT 1;
   IF k IS NULL THEN RAISE EXCEPTION 'Khong tim thay khung gio cho lop %',c.malophoc; END IF;
   b:=c.malophoc||'-'||d||'-'||e.key;
   start_at:=(d+times[1]::time) AT TIME ZONE 'Asia/Bangkok'; end_at:=(d+times[2]::time) AT TIME ZONE 'Asia/Bangkok';
   completed:=(e.value->>'status') IN ('Đã hoàn thành','Dạy thay');
   gv:=coalesce(e.value->>'coverTeacherId',c.magiaovien);
   VALUES(b,c.madinhdanh,d,k,start_at,end_at,c.magiaovien,e.value->>'coverTeacherId',e.value->>'title',c.lienketphonghoc,
    CASE WHEN completed THEN 'HOAN_THANH' WHEN e.value->>'status'='Nghỉ có phép' THEN 'NGHI_HOC' ELSE 'CHUA_DIEN_RA' END,
    CASE WHEN completed THEN (d+coalesce(e.value->>'checkinTime',times[1])::time) AT TIME ZONE 'Asia/Bangkok' END,
    CASE WHEN completed THEN end_at END,CASE WHEN completed THEN gv END,CASE WHEN completed THEN gv END,e.value->>'teacherAttendance','Du lieu thu TEST') ON CONFLICT DO NOTHING;
   FOR h IN SELECT key,value FROM jsonb_each_text(coalesce(e.value->'attendance','{}')) LOOP
   END LOOP;
   FOR h IN SELECT key,value FROM jsonb_each_text(coalesce(e.value->'feedback','{}')) LOOP
    VALUES(b,h.key,h.value,coalesce(e.value->'feedbackCriteria'->h.key,'{}'),'khich-le',gv) ON CONFLICT DO NOTHING;
   END LOOP;
  END LOOP;
 END LOOP;
END $seed$;
